import io
import logging

from PIL import Image
from pyzbar.pyzbar import decode

from bot.services.crypto_local import Crypto

PRIVATE_RSA_KEY = ""

logger = logging.getLogger(__name__)


def decode_qr_from_bytes(image_bytes: bytes) -> str | None:
    try:
        image = Image.open(io.BytesIO(image_bytes))
        decoded = decode(image)
        if decoded:
            raw = decoded[0].data.decode("utf-8", errors="ignore").strip()
            return _resolve_qr(raw)
    except Exception as e:
        logger.error("QR decode error: %s", e)
    return None


def decode_qr_from_text(text: str) -> str | None:
    text = text.strip()
    return _resolve_qr(text)


def _resolve_qr(raw: str) -> str | None:
    if not raw:
        return None

    if ";" in raw:
        parts = raw.split(";")
        first_part = parts[0].strip()
        second_part = parts[1].strip() if len(parts) > 1 else ""

        if first_part and second_part:
            decrypted = Crypto.decrypt_aes(first_part, PRIVATE_RSA_KEY, second_part)
            if decrypted:
                return decrypted.upper()

    return raw.upper()
